def main():
 p=argparse.ArgumentParser();p.add_argument('--input',required=True);p.add_argument('--annotation',required=True);p.add_argument('--d8',required=True);p.add_argument('--output',required=True);a=p.parse_args();out=Path(a.output);out.mkdir(parents=True,exist_ok=True);im=cv2.imread(a.input);cfg=load_config(Path(a.input).parents[2]/'configs/default.yaml');view=make_image_view(im,cfg.pipeline.roi,896);g=cv2.GaussianBlur(select_gray_channel(view.image,cfg.seam.color_channel),(5,5),0);rot,valid,m=__import__('scripts.experiment_real_seam_orientation',fromlist=['rotate_processing_image']).rotate_processing_image(g,0)
