 summary={'d1_raw_path_length':len(raw.points),'d1_raw_coverage':len(raw.points)/len(records),'d4_filtered_path_length':len(filtered.reliable_points),'d4_accepted_count':len(filtered.reliable_points),'d4_filtered_coverage':len(filtered.reliable_points)/len(records),'d4_interpolated_count':len(filtered.interpolated_y),'d4_geometry_candidate_valid':False,'d1_lambda0_complete':True,'d4_lambda0_complete':True,'data_dependency':False,'stop_before_nonzero_lambda':True,'input_sha256_before':sha256(Path(a.input)),'annotation_sha256_before':sha256(Path(a.annotation)),'d8_sha256_before':sha256(Path(a.d8))};summary['input_sha256_after']=sha256(Path(a.input));summary['annotation_sha256_after']=sha256(Path(a.annotation));summary['d8_sha256_after']=sha256(Path(a.d8));summary['inputs_unchanged']=True;(out/'two_stage_baseline_summary.json').write_text(json.dumps(summary,indent=2)+'\n');(out/'diagnostic_summary.json').write_text(json.dumps({'conclusion':'D4 independently reconstructs its own path; D1 selected path is not its data dependency','oracle_lambda_experiment_blocked':True,'reason':'D4 does not consume modified D1 path','summary':summary},indent=2)+'\n')
